<?php
declare(strict_types=1);require __DIR__.'/invoice-list-v3.php';exit;
$pdo=db();$invoices=$pdo->query('SELECT LOWER(TRIM(m.invoice_no)) invoice_key,MAX(m.id) movement_id,MAX(m.movement_type) movement_type,MAX(m.invoice_no) invoice_no,MIN(m.movement_date) movement_date,MAX(c.code) account_code,MAX(COALESCE(c.short_name,c.title)) account_name,COUNT(*) line_count,SUM(COALESCE(m.purchase_price,0)+ROUND(COALESCE(m.purchase_price,0)*COALESCE(m.vat_rate,0)/100,2)) total FROM stock_movements m LEFT JOIN current_accounts c ON c.id=m.current_account_id WHERE TRIM(COALESCE(m.invoice_no,""))<>"" GROUP BY LOWER(TRIM(m.invoice_no)),m.movement_type ORDER BY MIN(m.movement_date) DESC,MAX(m.id) DESC')->fetchAll();
patient_header('Fatura Listesi','stock');?>
<main class="patient-container invoice-list"><section class="technical-card"><header><div><h1><i class="ti tabler-file-invoice"></i> Fatura Listesi</h1><p>Stok giriş ve çıkış faturaları.</p></div><a class="button invoice-add" href="<?=e(url('invoice-entry.php'))?>">Fatura Girişi</a></header><div class="technical-table-wrap"><table><thead><tr><th>FATURA NO</th><th>TARİH</th><th>HAREKET YÖNÜ</th><th>CARİ</th><th>KALEM</th><th>ALIŞ FİYATI (KDV'Lİ)</th><th>İŞLEM</th></tr></thead><tbody><?php foreach($invoices as $invoice):?><tr><td><?=e($invoice['invoice_no'])?></td><td><?=e(format_date_tr($invoice['movement_date']))?></td><td><?=e($invoice['movement_type'])?></td><td><?=e(trim(($invoice['account_code']?'CR-'.$invoice['account_code'].' — ':'').$invoice['account_name']))?></td><td><?=e((string)$invoice['line_count'])?></td><td><?=e(number_format((float)$invoice['total'],2,',','.'))?> TL</td><td><?php if($invoice['movement_type']==='Giriş'):?><a class="invoice-edit" href="<?=e(url('stock-entry.php?new=1&edit='.(int)$invoice['movement_id']))?>">Düzenle</a><?php else:?><span>—</span><?php endif?></td></tr><?php endforeach;if(!$invoices):?><tr><td colspan="7" class="empty">Henüz fatura girişi bulunmuyor.</td></tr><?php endif?></tbody></table></div></section></main><style>.invoice-list{max-width:1500px;margin:30px auto}.technical-card{background:#fff;border:1px solid #e1e2e8;border-radius:10px;overflow:hidden}.technical-card>header{display:flex;align-items:center;justify-content:space-between;padding:22px 24px;border-bottom:1px solid #e1e2e8}.technical-card h1{margin:0 0 5px}.technical-card p{margin:0;color:#7b7b8d}.invoice-add,.invoice-edit{text-decoration:none}.invoice-edit{color:#19a94b;font-weight:600}.technical-card table{width:100%;border-collapse:collapse}.technical-card th,.technical-card td{padding:14px 18px;border-bottom:1px solid #e1e2e8;text-align:left}.technical-card th{font-size:12px;color:#5d5b6d}.empty{text-align:center;color:#7b7b8d}</style><?php patient_footer();?>
